    const size_t AES_KEY_LENGTH_BYTES = 32; // For AES-256 (256 bits)
    // AES_BLOCK_SIZE is a macro defined in openssl/aes.h, typically 16 bytes.

    // 1. Prepare the key: Use the prefix of the provided key bytes
    // The docstring guarantees key.size() >= 64, so it's definitely >= AES_KEY_LENGTH_BYTES.
    std::vector<uint8_t> encryption_key(key.begin(), key.begin() + AES_KEY_LENGTH_BYTES);

